    """
def convert_LengthUnit(len_unit1: Any, len_unit: Any) -> object {
    if ((len_unit1 == "") or (len_unit1 == len_unit)) {
        return (len_unit, 1);
    }
    dictC = {
        "ft_km": 0.0003048,
        "kt_km": 1.852,
        "mi_km": 1.609344,
        "m_km": 0.001,
        "km_ft": 3280.8399,
        "km_kt": 0.53996,
        "km_mi": 0.621371,
        "km_m": 1000,
        "km_km": 1
    };
    s1 = len_unit + "_km";
    s2 = "km_" + len_unit1;
    val = dictC[s1] * dictC[s2];
    return (len_unit1, val);
}

"""
        ## Example
        `isSubKey("Rocket", "Rocket.name")` -> True
        `isSubKey("SimControl", "Rocket.name")` -> False
    """
def isSubKey(potentialParent: str, potentialChild: str) -> bool {
    if (potentialParent == "") {
        return True;
    }
    pLength = len(potentialParent);
    cLength = len(potentialChild);
    if (cLength <= pLength) {
        return False;
    } elif (
        (potentialChild[:pLength] == potentialParent)
        and (potentialChild[pLength] == ".")
    ) {
        return True;
    } else {
        return False;
    }
}

